const glossary: GlossaryTerm[] = [
  { slug: "bitcoin", term: "Bitcoin", category: "Bitcoin", shortDefinition: "Bitcoin is a peer-to-peer monetary network that records transfers on a public proof-of-work blockchain.", answer: "Bitcoin is an open network for sending and receiving value without a central ledger operator. Participants use cryptographic keys to authorize transfers, while miners compete to add blocks and nodes verify the rules.", whyItMatters: "Knowing what Bitcoin is prevents a common category error: BTC is the asset, while Bitcoin is the network and rule set that records ownership. The distinction matters when checking addresses, custody, confirmations, and fork claims.", example: "If Alice sends 0.01 BTC to Bob, her wallet creates a transaction, signs it with her private key, and broadcasts it. Miners may include it in a block; nodes then verify the signatures and the inputs before accepting the state change.", misconceptions: ["Bitcoin is not a company with a customer-service department; it is an open protocol.", "A Bitcoin wallet does not contain coins in the same way a physical wallet contains cash; it manages keys used to authorize transactions."], related: ["blockchain", "proof-of-work", "private-key", "transaction", "bitcoin-halving"], sources: [sources.bitcoinWhitepaper, sources.bitcoinDev], internalLinks: [{ label: "Read the Bitcoin Halving guide", url: "/tools/bitcoin-halving" }, { label: "Read the Bitcoin Forks guide", url: "/learn/bitcoin-forks" }] },
  { slug: "block-reward", term: "Block reward", category: "Bitcoin", shortDefinition: "A block reward is the compensation paid to the miner or validator that produces an accepted block.", answer: "A Bitcoin block reward is mainly the newly issued subsidy plus the transaction fees included in the block. The subsidy follows the protocol schedule and is reduced at halving intervals; fees vary with demand.", whyItMatters: "The block reward helps explain why miners spend money on electricity and hardware. It also explains why halvings change the economics of mining without changing the rules for previously confirmed coins.", example: "After the 2024 Bitcoin halving, the scheduled subsidy became 3.125 BTC per block. A miner’s actual gross reward can be higher if the block also contains transaction fees, but the subsidy and fees are separate components.", misconceptions: ["The reward is not a guaranteed profit; operating costs can exceed the coins and fees received.", "A block reward is not the same as the total value of every transaction in the block."], related: ["bitcoin-halving", "mining", "difficulty-adjustment", "transaction"], sources: [sources.bitcoinBlocks, sources.bitcoinHalving], internalLinks: [{ label: "Track the Bitcoin Halving countdown", url: "/tools/bitcoin-halving" }] },
  { slug: "bitcoin-halving", term: "Bitcoin halving", category: "Bitcoin", shortDefinition: "A Bitcoin halving is a scheduled reduction in the new BTC subsidy paid per mined block.", answer: "A Bitcoin halving cuts the block subsidy in half after another 210,000 blocks are added. It changes the rate of new issuance; it does not promise a price move or guarantee that mining remains profitable.", whyItMatters: "Halvings make Bitcoin’s issuance schedule easier to audit and help readers separate protocol mechanics from market commentary. The target block is precise, while the calendar date is only an estimate because block times vary.", example: "At block 840,000 in April 2024, the subsidy moved from 6.25 BTC to 3.125 BTC. The next scheduled target is block 1,050,000, where the subsidy is expected to become 1.5625 BTC.", misconceptions: ["A halving does not delete coins already recorded on the network.", "A countdown to a block is not a forecast of Bitcoin’s future price."], related: ["bitcoin", "block-reward", "mining", "proof-of-work"], sources: [sources.bitcoinHalving, sources.bitcoinBlocks], internalLinks: [{ label: "Open the live Bitcoin Halving tool", url: "/tools/bitcoin-halving" }] },
  { slug: "proof-of-work", term: "Proof of work", category: "Bitcoin", shortDefinition: "Proof of work is a consensus method that uses computational work to make block production costly and verifiable.", answer: "Proof of work lets a network choose a chain by requiring miners to find valid hashes under a difficulty target. Other nodes can verify the result quickly, even though finding it required repeated computation.", whyItMatters: "The model links Bitcoin’s security, mining competition, energy use, difficulty adjustment, and block timing. It also clarifies why changing mining rules can affect hardware, pools, and chain security.", example: "A miner repeatedly changes a block header nonce and hashes the candidate. The miner succeeds only when the resulting hash falls below the network target; nodes then check the block and its proof.", misconceptions: ["Proof of work does not mean miners solve a useful business calculation; the work secures consensus.", "A higher energy bill does not automatically mean a miner has a stronger individual chance; hashrate share matters."], related: ["mining", "difficulty-adjustment", "consensus", "block"], sources: [sources.bitcoinWhitepaper, sources.bitcoinBlocks], internalLinks: [{ label: "Learn how forks change network rules", url: "/learn/bitcoin-forks" }] },
  { slug: "mining", term: "Mining", category: "Bitcoin", shortDefinition: "Mining is the process of assembling transactions and competing to add a valid proof-of-work block.", answer: "Bitcoin mining is the process of using specialized hardware to search for a valid block hash. A successful miner publishes the block, and the network’s nodes independently verify its transactions and proof.", whyItMatters: "Mining affects confirmation incentives, electricity demand, hardware markets, pool concentration, and the economics of the Bitcoin network. A simple cost estimate is never the same as a complete operating-profit calculation.", example: "A mining pool combines the work of many machines and distributes payouts according to contributed shares. The pool does not remove the need for each machine to run Bitcoin-compatible mining software and hardware.", misconceptions: ["Mining is not performed by ordinary wallet apps.", "A miner can find a valid block but still lose money after electricity, equipment, hosting, financing, and pool costs."], related: ["proof-of-work", "block-reward", "difficulty-adjustment", "bitcoin-halving"], sources: [sources.bitcoinBlocks, sources.bitcoinDev], internalLinks: [{ label: "Explore the Halving mining-cost model", url: "/tools/bitcoin-halving" }] },
  { slug: "difficulty-adjustment", term: "Difficulty adjustment", category: "Bitcoin", shortDefinition: "Difficulty adjustment changes the mining target so Bitcoin’s average block interval stays near its protocol goal.", answer: "Bitcoin periodically adjusts mining difficulty in response to how quickly recent blocks were produced. More total computing power can raise difficulty, while less power can lower it, although individual blocks still arrive unevenly.", whyItMatters: "Difficulty helps explain why a sudden change in hashrate does not permanently make blocks arrive faster. It is also a key input for mining-cost discussions and network-security analysis.", example: "If recent blocks were found faster than the target interval, the next adjustment makes valid hashes harder to find. Miners then need more expected computation to produce a block.", misconceptions: ["Difficulty is not a measure of how complicated a transaction is.", "Difficulty does not make every block take exactly the same amount of time; it changes the probability distribution."], related: ["mining", "proof-of-work", "block", "block-reward"], sources: [sources.bitcoinBlocks] },
  { slug: "blockchain", term: "Blockchain", category: "Blockchain", shortDefinition: "A blockchain is an ordered, shared record of state changes grouped into linked blocks.", answer: "A blockchain is a data structure and coordination system in which participants agree on an ordered history of transactions or other state changes. Different networks use different rules for validation, consensus, and finality.", whyItMatters: "The word is often used as if every chain works the same way. Checking the actual network, consensus model, upgrade process, and finality assumptions is more useful than relying on the label alone.", example: "A block may contain transactions, a reference to the previous block, a timestamp, and consensus-specific data. Nodes validate the block before extending their view of the chain.", misconceptions: ["A blockchain is not automatically decentralized just because it uses blocks.", "Putting data on a blockchain does not make the data private or correct by itself."], related: ["block", "transaction", "consensus", "layer-1"], sources: [sources.bitcoinWhitepaper, sources.bitcoinDev] },
  { slug: "block", term: "Block", category: "Blockchain", shortDefinition: "A block is a batch of network-approved transactions or state changes added to a blockchain.", answer: "A block packages new transactions with metadata that lets nodes check its position and validity. The exact fields vary by network, but blocks normally link to earlier history and follow the chain’s consensus rules.", whyItMatters: "Understanding blocks makes confirmations, reorgs, block explorers, mining, and finality easier to interpret. It also helps distinguish a pending transaction from one recorded in a block.", example: "When a Bitcoin transaction appears in block 850,000, an explorer can show the block hash, time, included transaction, and later blocks built on top of it.", misconceptions: ["A block confirmation is not the same as a guarantee that an exchange has credited a deposit.", "A block is not necessarily produced at a perfectly fixed time interval."], related: ["blockchain", "transaction", "consensus", "proof-of-work"], sources: [sources.bitcoinBlocks] },
  { slug: "transaction", term: "Transaction", category: "Blockchain", shortDefinition: "A blockchain transaction is a signed instruction that asks the network to change ownership or application state.", answer: "A transaction carries the data needed for a network to validate a state change, such as spending an input, transferring tokens, or calling a smart contract. The sender authorizes it with a cryptographic signature.", whyItMatters: "A transaction can be valid yet still pending, rejected, replaced, or expensive to execute. Checking the network, fee, destination, and confirmation state matters before assuming funds arrived.", example: "Bob sends 0.01 BTC to Alice’s address. His wallet signs the transaction, miners include it in a block, and nodes verify that the inputs were not already spent.", misconceptions: ["A transaction broadcast to the network is not automatically final.", "A blockchain transfer cannot usually be reversed by customer support once confirmed under the network’s rules."], related: ["block", "private-key", "public-key", "consensus"], sources: [sources.bitcoinTransactions, sources.bitcoinDev] },
  { slug: "consensus", term: "Consensus", category: "Blockchain", shortDefinition: "Consensus is the process by which network participants converge on an accepted blockchain state and rule set.", answer: "Blockchain consensus is not merely agreement in a chat room. It is the combination of validation rules and coordination mechanisms that lets independent nodes accept some blocks and reject others.", whyItMatters: "Consensus determines which transactions are valid, who can propose blocks, how conflicts settle, and how upgrades are adopted. A network’s security claims are inseparable from its consensus design.", example: "Two nodes may receive different transactions first, but after following the same validation and chain-selection rules they can converge on the same accepted history.", misconceptions: ["Consensus does not require every participant to communicate with every other participant directly.", "A governance vote can signal preference without automatically changing the rules enforced by nodes."], related: ["blockchain", "proof-of-work", "smart-contract", "layer-1"], sources: [sources.bitcoinBlocks, sources.ethereumContracts] },
  { slug: "smart-contract", term: "Smart contract", category: "Blockchain", shortDefinition: "A smart contract is blockchain-deployed code that executes according to predefined rules when called.", answer: "A smart contract is a program whose state and execution are handled by a blockchain or compatible execution environment. It can hold assets, enforce conditions, and interact with other contracts, but it cannot guarantee that its code matches a human promise.", whyItMatters: "Smart contracts introduce programmable finance but also create risks involving bugs, permissions, oracle inputs, upgrade keys, and irreversible calls. Reading a contract’s authority model matters as much as reading its marketing.", example: "A swap contract can accept one token, calculate an exchange according to its rules, and send another token back, with the transaction recorded on-chain.", misconceptions: ["A smart contract is not necessarily smart, legally binding, or free from bugs.", "Code running on-chain cannot independently know off-chain prices unless an oracle or signed data source supplies them."], related: ["decentralized-finance", "automated-market-maker", "rollup", "transaction"], sources: [sources.ethereumContracts, sources.ethereumDefi] },
  { slug: "layer-1", term: "Layer 1", category: "Blockchain", shortDefinition: "A layer 1 is a base blockchain that provides its own consensus, settlement, and native asset rules.", answer: "A layer 1 is the underlying network where transactions are validated and settled according to that chain’s own protocol. Bitcoin and Ethereum are examples, but their execution and consensus designs are different.", whyItMatters: "When a product says it supports a token, you still need to check which layer 1 and address format are involved. Sending an asset on the wrong network can make recovery difficult or impossible.", example: "A user may hold USDC on Ethereum, Base, or Solana. The ticker is similar, but the network, address format, fees, and supported withdrawal route can differ.", misconceptions: ["Layer 1 does not mean the network is automatically faster, safer, or more decentralized.", "A token bridged to a layer 1 is not necessarily native to that chain."], related: ["layer-2", "rollup", "blockchain", "consensus"], sources: [sources.ethereumLayer2, sources.bitcoinDev] },
  { slug: "layer-2", term: "Layer 2", category: "Blockchain", shortDefinition: "A layer 2 is a system built around a base blockchain to process activity with different cost or throughput trade-offs.", answer: "A layer 2 generally executes or batches activity away from the base layer and uses the underlying chain for settlement, data, or security. The exact trust and withdrawal model depends on the design.", whyItMatters: "Layer 2 is a category, not a guarantee. Users should check bridges, sequencers, fraud or validity proofs, withdrawal times, supported assets, and what happens if operators stop serving the system.", example: "A rollup may collect many user actions, publish data or proofs to Ethereum, and let users interact at a lower apparent cost than sending every action directly on Ethereum.", misconceptions: ["A lower fee does not mean a layer 2 has identical security or censorship properties to its base chain.", "Moving funds to a layer 2 usually involves a network-specific bridge or deposit route."], related: ["layer-1", "rollup", "smart-contract", "liquidity"], sources: [sources.ethereumLayer2] },
  { slug: "rollup", term: "Rollup", category: "Blockchain", shortDefinition: "A rollup batches transactions and uses a base blockchain for settlement, data availability, or verification.", answer: "A rollup executes many transactions outside the base chain and posts enough information or a proof for the base chain to settle the result. Optimistic and zero-knowledge designs use different verification and withdrawal assumptions.", whyItMatters: "Rollups can change fees and throughput, but readers must understand bridge trust, sequencer dependence, data availability, proof timing, and application compatibility before moving assets.", example: "A rollup operator combines hundreds of transfers into one batch, posts data to the base chain, and later finalizes the batch under the rollup’s proof rules.", misconceptions: ["Rollup does not mean every transaction is instantly final on the base chain.", "Two rollups using the same base chain can have different withdrawal and upgrade risks."], related: ["layer-1", "layer-2", "smart-contract", "consensus"], sources: [sources.ethereumLayer2] },
  { slug: "crypto-exchange", term: "Crypto exchange", category: "Trading", shortDefinition: "A crypto exchange is a service or protocol that matches, routes, or facilitates trades between digital assets and currencies.", answer: "A crypto exchange can be centralized, where the platform maintains an internal ledger and custody model, or decentralized, where smart contracts execute trades on-chain. The word alone does not describe the platform’s risks or controls.", whyItMatters: "Users need to distinguish account balances from on-chain custody, understand fees and withdrawal policies, and verify the exact network before depositing or withdrawing.", example: "A centralized exchange may match Alice’s BTC sell order with Bob’s buy order internally, while a decentralized exchange may use a liquidity pool and settle the swap through a contract.", misconceptions: ["An exchange listing does not prove an asset is safe or suitable.", "A displayed account balance on a custodial exchange is not the same as a self-custodied on-chain balance."], related: ["order-book", "market-order", "liquidity", "self-custody"], sources: [sources.cftcCrypto, sources.secInvestor], internalLinks: [{ label: "Compare exchange features", url: "/exchanges/best-crypto-exchanges-2026" }] },
  { slug: "order-book", term: "Order book", category: "Trading", shortDefinition: "An order book lists open buy and sell orders for an asset at different prices.", answer: "An order book is a live queue of bids from buyers and asks from sellers. Its visible depth can help explain spread and execution, but it can change quickly and may not show hidden or off-platform liquidity.", whyItMatters: "Order-book depth affects the likely execution price of a trade. Thin depth can make a seemingly small market order move the price more than expected.", example: "If the lowest ask is $100 and the next asks are $100.20 and $100.60, a large buy may fill across several levels instead of receiving one price.", misconceptions: ["Displayed orders are not guaranteed to remain until your trade reaches them.", "An order book does not show every source of liquidity in the market."], related: ["market-order", "limit-order", "spread", "slippage"], sources: [sources.cftcCrypto] },
  { slug: "market-order", term: "Market order", category: "Trading", shortDefinition: "A market order asks to buy or sell immediately at the best available prices.", answer: "A market order prioritizes execution over a specific price. The trade may fill across multiple order-book levels, especially when the market is thin, volatile, or the order is large relative to available liquidity.", whyItMatters: "The visible last-traded price is not a promise about the price your market order will receive. Reviewing depth, fees, and slippage is essential before submitting an order.", example: "A user submits a market buy for 1 ETH. The first part fills at the lowest ask, while the rest may fill at higher asks if the first level does not contain enough ETH.", misconceptions: ["Market order does not mean a guaranteed fair price.", "Fast execution does not remove trading fees or price impact."], related: ["order-book", "limit-order", "slippage", "volatility"], sources: [sources.cftcCrypto] },
  { slug: "limit-order", term: "Limit order", category: "Trading", shortDefinition: "A limit order sets the worst acceptable price at which a trade may execute.", answer: "A limit buy can execute at its limit price or lower, while a limit sell can execute at its limit price or higher. It may remain unfilled if the market never reaches the requested price or available liquidity is insufficient.", whyItMatters: "Limit orders provide price control but not execution certainty. Users should understand time-in-force rules, partial fills, maker/taker fees, and what happens when an order expires.", example: "A trader places a limit buy for 0.5 BTC at $60,000. The order executes only at $60,000 or less under the venue’s matching rules.", misconceptions: ["A limit order is not a guarantee that the trade will happen.", "A displayed limit price does not include every fee or tax that may apply to the user."], related: ["order-book", "market-order", "spread", "liquidity"], sources: [sources.cftcCrypto] },
  { slug: "spread", term: "Spread", category: "Trading", shortDefinition: "The spread is the difference between the best available buy price and the best available sell price.", answer: "In an order book, the bid-ask spread is the gap between the highest visible bid and the lowest visible ask. It is one simple indicator of immediate trading friction, not a complete measure of market quality.", whyItMatters: "A wider spread can increase the cost of entering and exiting, particularly for smaller or less liquid assets. Comparing the spread across venues can reveal different execution conditions.", example: "If the highest bid is $99.90 and the lowest ask is $100.10, the displayed spread is $0.20 before fees and slippage.", misconceptions: ["The spread is not the same as the exchange’s published commission.", "A narrow spread at one moment can widen quickly during volatility or low activity."], related: ["order-book", "liquidity", "slippage", "volatility"], sources: [sources.cftcCrypto] },
  { slug: "liquidity", term: "Liquidity", category: "Trading", shortDefinition: "Liquidity is the availability of buyers and sellers that lets an asset trade without large price changes.", answer: "A liquid market can absorb trades with relatively limited price impact at the time measured. Liquidity depends on depth, venue, pair, time of day, market conditions, and the size and direction of the order.", whyItMatters: "Liquidity affects spreads, slippage, withdrawals, token exits, and the reliability of quoted prices. A high market cap alone does not guarantee liquidity for every pair or network.", example: "A token may show a large headline market value but have only a small amount available in its main pool. Selling a large position could then move the quoted price sharply.", misconceptions: ["Liquidity is not identical to trading volume; volume can be inflated or concentrated.", "A token’s liquidity on one chain does not automatically transfer to another chain."], related: ["spread", "slippage", "liquidity-pool", "market-order"], sources: [sources.uniswapDocs, sources.cftcCrypto], internalLinks: [{ label: "Research meme-token liquidity", url: "/meme-coin-research" }] },
  { slug: "slippage", term: "Slippage", category: "Trading", shortDefinition: "Slippage is the difference between an expected trade price and the price or average price actually received.", answer: "Slippage occurs when market conditions, order size, latency, or an automated execution rule causes the final fill to differ from the quote. It can be positive or negative, but traders usually worry about paying more or receiving less.", whyItMatters: "Slippage is especially important in thin markets and decentralized exchanges. A slippage tolerance can limit execution, but setting it too high may allow an unexpectedly poor fill.", example: "A swap preview shows 1,000 tokens, but price movement and pool depth leave the user with 970 tokens. The difference may reflect price impact and slippage under the transaction’s rules.", misconceptions: ["Slippage tolerance is not a fee and cannot make an unsafe contract safe.", "A low tolerance can cause a transaction to fail rather than guarantee a better price."], related: ["liquidity", "spread", "automated-market-maker", "volatility"], sources: [sources.uniswapDocs, sources.ethereumDefi] },
  { slug: "volatility", term: "Volatility", category: "Trading", shortDefinition: "Volatility describes how much and how quickly an asset’s price changes over a chosen period.", answer: "Volatility is a measure of price variation, not a directional forecast. An asset can be volatile while rising, falling, or moving sharply in both directions.", whyItMatters: "High volatility affects liquidation risk, order execution, portfolio sizing, collateral values, and the chance that a quoted price becomes stale before a trade settles.", example: "If a token moves from $1.00 to $1.20 and then to $0.85 in a short period, its path is volatile even though the final price alone does not describe the journey.", misconceptions: ["Volatility does not mean an asset will go up.", "Historical volatility does not guarantee the same level of movement in the future."], related: ["liquidity", "slippage", "market-order", "order-book"], sources: [sources.cftcCrypto, sources.secInvestor] },
  { slug: "decentralized-finance", term: "Decentralized finance", category: "DeFi", shortDefinition: "Decentralized finance is a set of blockchain applications that provide financial functions through programmable protocols.", answer: "Decentralized finance, or DeFi, refers to on-chain applications for activities such as swapping, lending, borrowing, and staking without relying on one traditional intermediary for every transaction.", whyItMatters: "DeFi changes who controls funds and how transactions execute, but it adds smart-contract, oracle, liquidity, governance, bridge, and key-management risks. Permissionless access does not mean risk-free access.", example: "A user can deposit an asset into a lending protocol and receive a variable rate according to the protocol’s available liquidity and rules, rather than a fixed bank account promise.", misconceptions: ["DeFi does not mean there is no company, developer, multisignature, or admin key involved.", "A high displayed yield is not the same as a guaranteed return."], related: ["smart-contract", "automated-market-maker", "liquidity-pool", "lending-protocol"], sources: [sources.ethereumDefi, sources.ethereumContracts], internalLinks: [{ label: "Read the meme-token research checklist", url: "/meme-coin-research" }] },
  { slug: "automated-market-maker", term: "Automated market maker", category: "DeFi", shortDefinition: "An automated market maker uses a smart contract and pricing formula to quote swaps from available liquidity.", answer: "An automated market maker, or AMM, lets users trade against a liquidity pool rather than a traditional central order book. The pool’s assets and formula determine the quoted exchange rate.", whyItMatters: "AMMs make permissionless swaps possible, but price impact, arbitrage, impermanent loss, fees, oracle assumptions, and contract bugs affect the result.", example: "A constant-product pool quotes a token swap using the relative reserves of two assets. A large trade changes those reserves and therefore changes the next quoted price.", misconceptions: ["An AMM is not a guarantee that a token can be sold at the displayed price.", "The pool’s liquidity providers do not necessarily receive a risk-free fee stream."], related: ["liquidity-pool", "slippage", "impermanent-loss", "smart-contract"], sources: [sources.uniswapDocs, sources.ethereumDefi] },
  { slug: "liquidity-pool", term: "Liquidity pool", category: "DeFi", shortDefinition: "A liquidity pool is a smart-contract-held reserve of assets used to facilitate swaps or other protocol activity.", answer: "A liquidity pool holds one or more assets under a protocol’s rules. Users may trade against the reserves, while liquidity providers can receive fees or incentives in exchange for supplying capital.", whyItMatters: "Pool size, composition, concentration, contract permissions, and withdrawal conditions influence whether a trade can execute safely. A token with a tiny pool can have a misleading displayed price.", example: "A two-asset pool holds ETH and a token. A buyer removes some ETH and adds the token, changing the reserve ratio and the price available to the next trader.", misconceptions: ["Locked liquidity does not prove that the token contract is safe.", "A pool’s total value can change because prices move, not only because users add or remove funds."], related: ["automated-market-maker", "liquidity", "impermanent-loss", "slippage"], sources: [sources.uniswapDocs] },
  { slug: "impermanent-loss", term: "Impermanent loss", category: "DeFi", shortDefinition: "Impermanent loss is the relative underperformance a liquidity provider can experience compared with simply holding the deposited assets.", answer: "Impermanent loss occurs when the prices of assets in a liquidity pool move relative to each other, changing the pool’s rebalancing outcome. It may be offset by fees, but the loss is not automatically recovered.", whyItMatters: "A pool can show attractive fee income while the provider still ends with less value than a hold-only comparison. Concentrated-liquidity ranges can make the exposure more active and more sensitive to price movement.", example: "A provider deposits equal values of ETH and a token. If the token doubles relative to ETH, arbitrage changes the pool’s mix, leaving the provider with a different asset balance than a passive holder would have had.", misconceptions: ["Impermanent loss is not limited to assets that fall in price; relative price movement is the key factor.", "The word impermanent does not mean the loss will definitely disappear."], related: ["liquidity-pool", "automated-market-maker", "yield-farming", "volatility"], sources: [sources.uniswapDocs, sources.ethereumDefi] },
  { slug: "yield-farming", term: "Yield farming", category: "DeFi", shortDefinition: "Yield farming is the practice of supplying assets to DeFi protocols to pursue fees, incentives, or other variable returns.", answer: "Yield farming involves moving or depositing assets into one or more protocols in search of yield. The displayed rate can change with usage, token incentives, prices, emissions, and contract conditions.", whyItMatters: "A headline APY can hide smart-contract risk, impermanent loss, token dilution, liquidation, bridge risk, and withdrawal restrictions. The return should be evaluated alongside the risks and assumptions.", example: "A liquidity pool offers trading fees plus a temporary token incentive. The combined displayed APY may fall when volume decreases or when the incentive emissions change.", misconceptions: ["APY is not a guaranteed interest rate.", "A reward token can lose value even while the displayed token quantity increases."], related: ["staking", "liquidity-pool", "impermanent-loss", "lending-protocol"], sources: [sources.ethereumDefi, sources.ethereumContracts] },
  { slug: "staking", term: "Staking", category: "DeFi", shortDefinition: "Staking is committing assets to support a proof-of-stake network or protocol under defined reward and penalty rules.", answer: "In proof-of-stake systems, staking generally involves locking or delegating assets so validators can participate in consensus. Rewards, penalties, liquidity, withdrawal periods, and validator behavior depend on the network.", whyItMatters: "Staking can introduce lockups, slashing, validator risk, smart-contract risk, and variable rewards. Liquid-staking tokens add another layer of price and redemption risk.", example: "A user delegates ETH to a validator service and receives a representation of the position. The user must check the service’s custody, fees, withdrawal process, and smart-contract assumptions.", misconceptions: ["Staking is not the same as lending and does not have one universal reward rate.", "A staking yield does not eliminate the risk that the underlying asset falls in price."], related: ["proof-of-work", "lending-protocol", "yield-farming", "self-custody"], sources: [sources.ethereumStaking] },
  { slug: "lending-protocol", term: "Lending protocol", category: "DeFi", shortDefinition: "A lending protocol uses smart contracts to let users supply or borrow assets according to collateral and interest rules.", answer: "A DeFi lending protocol matches supplied liquidity with borrowers through an on-chain ruleset. Interest rates, collateral ratios, liquidation thresholds, and available assets are determined by the protocol’s design and current utilization.", whyItMatters: "Borrowing can create liquidation risk, while supplying can expose users to oracle failures, bad debt, contract bugs, and liquidity constraints. A variable rate can change rapidly.", example: "A user deposits ETH as collateral and borrows a stable-value token. If ETH falls below the protocol’s threshold, part of the collateral may be sold to repay the loan.", misconceptions: ["Overcollateralization does not make liquidation impossible.", "The protocol’s displayed supply rate is not a bank-insured deposit rate."], related: ["decentralized-finance", "smart-contract", "staking", "liquidity-pool"], sources: [sources.ethereumDefi, sources.ethereumContracts] },
  { slug: "crypto-wallet", term: "Crypto wallet", category: "Wallets and security", shortDefinition: "A crypto wallet manages the keys and software needed to view and authorize blockchain transactions.", answer: "A crypto wallet is an interface and key-management system, not a container that physically stores coins. The blockchain records balances; the wallet helps the user generate addresses, sign transactions, and monitor activity.", whyItMatters: "The wallet type affects recovery, signing security, convenience, phishing exposure, and who controls the keys. A custodial account and a self-custody wallet are not equivalent.", example: "A wallet may show a token balance by reading the chain, then ask the user to approve a signed transaction that transfers or swaps the asset.", misconceptions: ["Deleting a wallet app does not necessarily delete the on-chain assets if the keys can be restored.", "A wallet interface cannot reverse a confirmed transaction."], related: ["private-key", "public-key", "seed-phrase", "self-custody"], sources: [sources.bitcoinTransactions], internalLinks: [{ label: "Read seed phrase safety", url: "/learn/seed-phrase-security" }, { label: "Compare wallet guides", url: "/wallets/best-crypto-wallets-2026" }] },
  { slug: "private-key", term: "Private key", category: "Wallets and security", shortDefinition: "A private key is a secret cryptographic value that can authorize spending from a blockchain address.", answer: "A private key is secret data used to create a valid signature for a transaction. Anyone who obtains the relevant key may be able to control the associated assets, while the network can verify a signature without seeing the secret.", whyItMatters: "Private-key exposure is usually a control failure, not a customer-service problem. Safe key handling means avoiding screenshots, chat messages, cloud notes, fake support forms, and untrusted signing prompts.", example: "Alice’s wallet uses a private key to sign a 0.01 BTC transfer. Bob and the network can verify the signature, but the private key itself should never be published.", misconceptions: ["A private key is not a password that can be reset by an exchange.", "A seed phrase can derive multiple keys; it is not always one-to-one with one address."], related: ["public-key", "seed-phrase", "self-custody", "hardware-wallet"], sources: [sources.bitcoinTransactions], internalLinks: [{ label: "Review seed phrase security", url: "/learn/seed-phrase-security" }] },
  { slug: "public-key", term: "Public key", category: "Wallets and security", shortDefinition: "A public key is cryptographic information that helps verify signatures or derive an address, depending on the network.", answer: "A public key can be shared so others can verify signatures or use it in address-generation rules. It is related to a private key mathematically, but publishing the public key should not reveal the private key under the intended cryptographic assumptions.", whyItMatters: "Public keys, addresses, and account identifiers are related but not identical in every network. Understanding the difference helps avoid sending assets to the wrong format or confusing visibility with spending authority.", example: "A wallet may derive an address from a public key and share the address for receiving. The recipient still needs the corresponding private key to authorize a spend.", misconceptions: ["A public key is not a private key that has been made visible by accident.", "A public address can be observable without proving who controls it."], related: ["private-key", "crypto-wallet", "transaction", "self-custody"], sources: [sources.bitcoinTransactions] },
  { slug: "seed-phrase", term: "Seed phrase", category: "Wallets and security", shortDefinition: "A seed phrase is a human-readable backup that can recreate a wallet’s derived keys.", answer: "A seed phrase is a sequence of words generated according to a wallet standard and used to derive one or more private keys. Anyone who has the phrase may be able to restore and control the wallet.", whyItMatters: "The phrase is often the most sensitive recovery secret in a self-custody setup. It should be stored offline, never typed into a website, and never shared with support, an app, or an alleged airdrop claim page.", example: "A wallet is lost, but the owner restores it on a replacement device using the correct seed phrase. The app derives the same accounts and displays the on-chain balances.", misconceptions: ["A seed phrase is not a customer-support ticket or a password-reset code.", "A photo of a seed phrase is still a digital copy that can leak through backups or account compromise."], related: ["private-key", "self-custody", "hardware-wallet", "phishing"], sources: [sources.bitcoinDev], internalLinks: [{ label: "Read the full seed phrase safety guide", url: "/learn/seed-phrase-security" }] },
  { slug: "hardware-wallet", term: "Hardware wallet", category: "Wallets and security", shortDefinition: "A hardware wallet is a dedicated device designed to keep signing operations isolated from a general-purpose computer or phone.", answer: "A hardware wallet stores or uses key material in a dedicated device and asks the user to confirm transactions on the device. It can reduce some online exposure, but it does not protect against every phishing, supply-chain, or approval mistake.", whyItMatters: "Hardware isolation can make key extraction harder, but the recovery phrase, firmware process, screen verification, and user decisions remain critical. A hardware wallet is not a substitute for careful transaction review.", example: "A user checks the recipient address and amount on the hardware wallet’s display before approving a transfer, rather than trusting only the computer screen.", misconceptions: ["A hardware wallet does not make a malicious transaction harmless if the user approves it.", "The device does not restore funds if the recovery phrase was exposed or recorded incorrectly."], related: ["crypto-wallet", "private-key", "seed-phrase", "self-custody"], sources: [sources.bitcoinDev], internalLinks: [{ label: "Compare wallet approaches", url: "/wallets/best-crypto-wallets-2026" }] },
  { slug: "software-wallet", term: "Software wallet", category: "Wallets and security", shortDefinition: "A software wallet is an application or browser extension that manages keys and signs transactions on a connected device.", answer: "A software wallet uses an app, browser extension, or operating-system application to generate, store, or access keys. It is convenient, but its security depends on the device, app, permissions, backups, and user habits.", whyItMatters: "Software wallets are common entry points for phishing, malicious extensions, clipboard replacement, and unsafe contract approvals. Convenience should be paired with small test transfers and careful permission review.", example: "A browser wallet asks the user to approve a token allowance for a decentralized application. The user should confirm the domain, contract, asset, and allowance scope first.", misconceptions: ["A wallet’s polished design does not prove that its code or download source is authentic.", "Uninstalling an app does not invalidate keys or revoke approvals."], related: ["crypto-wallet", "self-custody", "phishing", "private-key"], sources: [sources.ethereumContracts], internalLinks: [{ label: "Review seed phrase safety", url: "/learn/seed-phrase-security" }] },
  { slug: "self-custody", term: "Self-custody", category: "Wallets and security", shortDefinition: "Self-custody means the user controls the keys or signing authority needed to move the assets.", answer: "Self-custody places transaction authorization with the user rather than a platform account. It can reduce reliance on a custodian, but it transfers recovery, key security, signing, and error-management responsibilities to the user.", whyItMatters: "There is no universal undo button for a lost phrase, wrong network, or malicious approval. Self-custody is a control model with responsibilities, not a badge that automatically makes funds safer.", example: "A user holds a hardware wallet and keeps the recovery phrase offline. The user must still verify addresses, update the device safely, and plan recovery without disclosing the phrase.", misconceptions: ["Self-custody does not mean the user controls the blockchain’s rules.", "Keeping keys yourself does not eliminate smart-contract, market, bridge, or device risks."], related: ["private-key", "seed-phrase", "hardware-wallet", "multi-signature"], sources: [sources.bitcoinDev], internalLinks: [{ label: "Review wallet safety guidance", url: "/learn/seed-phrase-security" }] },
  { slug: "multi-signature", term: "Multisignature", category: "Wallets and security", shortDefinition: "Multisignature custody requires more than one approved key or signer before a transaction can execute.", answer: "A multisignature wallet divides spending authority across multiple keys and sets a threshold, such as two of three signers. It can reduce single-key failure but introduces coordination and recovery requirements.", whyItMatters: "Multisignature setups can protect treasuries, teams, and family funds from one lost or compromised key. The policy is only useful if signers, devices, backups, and recovery procedures are maintained.", example: "A two-of-three wallet needs signatures from any two designated devices before sending funds. One lost device does not automatically make the treasury unrecoverable.", misconceptions: ["Multisignature does not mean the keys are held by a regulated bank.", "A threshold policy can still fail if enough signers are compromised or the transaction is misread."], related: ["self-custody", "private-key", "hardware-wallet", "crypto-wallet"], sources: [sources.bitcoinDev] },
  { slug: "phishing", term: "Phishing", category: "Wallets and security", shortDefinition: "Phishing is a social-engineering attack that tricks a person into revealing secrets or approving an unsafe action.", answer: "Phishing uses fake websites, messages, support accounts, wallet pop-ups, or urgent claims to imitate a trusted service. The goal may be to steal a seed phrase, private key, login, or transaction approval.", whyItMatters: "Many crypto losses happen because a user authorizes the wrong action rather than because the underlying cryptography fails. Domain checks, bookmarks, hardware-screen review, and skepticism toward urgency reduce exposure.", example: "A message says a wallet will be frozen unless the user enters a seed phrase on a claim page. The request is a phishing attempt; no legitimate recovery flow needs the phrase.", misconceptions: ["A message is not trustworthy because it knows the user’s public address.", "A padlock in the browser does not prove that a website is the official service."], related: ["seed-phrase", "private-key", "software-wallet", "rug-pull"], sources: [sources.secInvestor], internalLinks: [{ label: "Read seed phrase safety", url: "/learn/seed-phrase-security" }] },
  { slug: "rug-pull", term: "Rug pull", category: "Wallets and security", shortDefinition: "A rug pull is a crypto project failure or scam in which insiders drain funds, abandon obligations, or remove meaningful liquidity.", answer: "A rug pull usually describes a project where insiders use privileged control, misleading promotion, or liquidity access to leave users with losses. The exact mechanism can involve a token contract, pool, treasury, presale, or platform.", whyItMatters: "A token can have an active community and attractive chart while still containing dangerous permissions or concentrated control. Contract review, holder analysis, liquidity checks, and team transparency are useful but not guarantees.", example: "A token creator retains the ability to mint unlimited supply and removes most of the trading pool after promotion drives buyers in. Holders may be unable to exit near the quoted price.", misconceptions: ["Locked liquidity alone does not prove that the contract or team is safe.", "A large follower count is not independent evidence of solvency or honest intent."], related: ["phishing", "liquidity", "smart-contract", "tokenomics"], sources: [sources.secInvestor], internalLinks: [{ label: "Use the meme-token research checklist", url: "/meme-coin-research" }] },
  { slug: "kyc", term: "KYC", category: "Regulation and taxes", shortDefinition: "KYC means identity-verification procedures used by a service to understand who its customer is.", answer: "Know Your Customer, or KYC, is a process in which a financial or crypto service collects and checks identity information. The exact documents, timing, and legal basis vary by provider and jurisdiction.", whyItMatters: "KYC can affect account access, limits, withdrawals, privacy, and the records a service keeps. A user should read the provider’s privacy notice and local rules rather than assume every platform handles identity data the same way.", example: "An exchange may ask for a government ID and proof of address before allowing fiat deposits or higher withdrawal limits.", misconceptions: ["KYC is not a technical feature of a blockchain itself.", "Passing KYC does not prove that an exchange is solvent, secure, or suitable."], related: ["aml", "regulatory-compliance", "tax-residence", "self-custody"], sources: [sources.fatfVirtualAssets], internalLinks: [{ label: "Browse the No KYC guide", url: "/exchanges/no-kyc" }] },
  { slug: "aml", term: "AML", category: "Regulation and taxes", shortDefinition: "AML refers to controls designed to prevent and detect money laundering and related financial crime.", answer: "Anti-money-laundering, or AML, describes policies and controls used to identify suspicious activity, verify customers, monitor transactions, and report certain activity under applicable law.", whyItMatters: "AML controls can affect account reviews, transaction holds, source-of-funds questions, and access to services. The requirements differ across jurisdictions and do not make every platform equally safe.", example: "A service may review a deposit pattern that does not match a customer’s profile and ask for information about the source of funds.", misconceptions: ["AML is not the same as blockchain transaction privacy.", "An AML check is not a guarantee that an asset or counterparty is legitimate."], related: ["kyc", "regulatory-compliance", "tax-residence", "crypto-exchange"], sources: [sources.fatfVirtualAssets] },
  { slug: "tax-residence", term: "Tax residence", category: "Regulation and taxes", shortDefinition: "Tax residence is the jurisdiction or jurisdictions that treat a person as resident for tax purposes under local rules.", answer: "Tax residence is determined by the laws and facts of a person’s situation, which can include days present, home, family, employment, and other connections. It is not always identical to citizenship or the country where an exchange account is registered.", whyItMatters: "Crypto reporting and tax treatment often depend on residence. A glossary can explain the concept, but only a qualified adviser or tax authority can assess a specific person’s filing position.", example: "A person who works remotely across countries may need to examine each jurisdiction’s residence tests before deciding how digital-asset gains are reported.", misconceptions: ["Citizenship alone does not always determine tax residence.", "Using a foreign exchange does not automatically move a taxpayer’s obligations to that exchange’s country."], related: ["capital-gains", "kyc", "regulatory-compliance", "tokenomics"], sources: [sources.irsResidency] },
  { slug: "capital-gains", term: "Capital gains", category: "Regulation and taxes", shortDefinition: "A capital gain is generally the increase in value recognized when an asset is disposed of, subject to the relevant tax rules.", answer: "Capital-gains tax concepts can apply when a person sells, exchanges, or otherwise disposes of an asset for more than its tax basis. Crypto treatment varies by jurisdiction and by the type of activity.", whyItMatters: "Swapping one token for another or spending crypto may have tax consequences even when no bank withdrawal occurs. Recordkeeping for dates, amounts, fees, basis, and transaction purpose is important.", example: "A taxpayer buys an asset for $1,000 and later disposes of it for $1,400. The taxable calculation depends on local rules, basis, holding period, fees, and the nature of the transaction.", misconceptions: ["A price increase on an asset that has not been disposed of is not treated identically in every tax system.", "This definition is not personal tax advice or a filing calculation."], related: ["tax-residence", "tokenomics", "crypto-exchange", "regulatory-compliance"], sources: [sources.irsDigitalAssets] },
  { slug: "regulatory-compliance", term: "Regulatory compliance", category: "Regulation and taxes", shortDefinition: "Regulatory compliance means following the laws, licensing conditions, reporting duties, and controls that apply to a service or activity.", answer: "Crypto regulatory compliance is the process of meeting applicable legal and supervisory obligations. The answer depends on the country, product, customer, asset, custody model, and activity involved.", whyItMatters: "A platform can be permitted in one market and unavailable in another. Users should verify current terms, licenses, restrictions, and complaint channels rather than rely on a global-sounding brand name.", example: "An exchange may offer spot trading in one jurisdiction but restrict derivatives, staking, or certain tokens in another because the regulatory perimeter differs.", misconceptions: ["Compliance status is not permanent; rules, licenses, and product permissions can change.", "A regulated service can still suffer outages, losses, hacks, or poor execution."], related: ["kyc", "aml", "tax-residence", "crypto-exchange"], sources: [sources.fatfVirtualAssets, sources.secInvestor] },
  { slug: "tokenomics", term: "Tokenomics", category: "Tokenomics", shortDefinition: "Tokenomics describes how a token is issued, distributed, used, and changed over time.", answer: "Tokenomics is the study of a token’s supply schedule, allocation, utility, incentives, unlocks, burns, and governance. It describes mechanics; it does not predict whether the token will gain value.", whyItMatters: "Supply concentration, emissions, vesting, unlock dates, and real demand can affect dilution and market liquidity. A token’s story should be checked against its contracts and published allocation details.", example: "A project may reserve 20% of its supply for contributors with a two-year vesting schedule. A future unlock can change circulating supply even if no new tokens are minted that day.", misconceptions: ["A low unit price does not mean a token is cheap; supply and valuation matter.", "Burning tokens does not automatically create sustainable demand."], related: ["circulating-supply", "max-supply", "inflation-rate", "vesting", "burn"], sources: [sources.ethereumTokens, sources.secInvestor] },
  { slug: "circulating-supply", term: "Circulating supply", category: "Tokenomics", shortDefinition: "Circulating supply is an estimate of the units currently available to the market under a provider’s methodology.", answer: "Circulating supply attempts to count tokens that are publicly available and not locked, vested, or otherwise excluded. Different data providers can classify wallets and contracts differently.", whyItMatters: "Market capitalization is often calculated as price multiplied by circulating supply. If the supply estimate is incomplete or inconsistent, comparisons can be misleading.", example: "A project reports 100 million tokens created but only 60 million unlocked and available. A market-data provider may use an estimate near the circulating amount, subject to its methodology.", misconceptions: ["Circulating supply is not always a perfect on-chain count.", "A token held by a large treasury may be technically transferable but still treated differently by a data provider."], related: ["max-supply", "tokenomics", "vesting", "inflation-rate"], sources: [sources.ethereumTokens, sources.secInvestor] },
  { slug: "max-supply", term: "Max supply", category: "Tokenomics", shortDefinition: "Max supply is the largest token quantity a project’s rules or documentation say can exist, if a cap is actually enforced.", answer: "Maximum supply is a stated or encoded ceiling on token units. Some assets have no fixed cap, some contracts can change the cap, and some data providers cannot verify the claim from public information alone.", whyItMatters: "A max-supply figure helps frame dilution, but it says nothing by itself about demand, distribution, liquidity, or whether governance can alter the rule.", example: "A token contract may limit minting to 1 billion units, while another project may describe a target supply that can be changed by an authorized upgrade.", misconceptions: ["Max supply is not the same as circulating supply.", "A stated cap is only meaningful if the code, governance, and upgrade authorities support it."], related: ["circulating-supply", "inflation-rate", "burn", "tokenomics"], sources: [sources.ethereumTokens] },
  { slug: "inflation-rate", term: "Inflation rate", category: "Tokenomics", shortDefinition: "A token inflation rate describes how quickly the supply increases under its issuance rules over a stated period.", answer: "In crypto tokenomics, inflation generally means new units are issued relative to an existing supply. The rate can be fixed, variable, governance-controlled, reward-driven, or offset by burns.", whyItMatters: "New issuance can dilute existing holders if demand does not grow at the same pace. Readers should check the denominator, time period, unlock schedule, and whether the rate is nominal or net of burns.", example: "A network issues 5 million new units against a 100 million starting supply. The simple nominal increase is 5%, but the effective rate may differ after burns or excluded locked balances.", misconceptions: ["Token inflation is not a forecast of consumer-price inflation.", "A high issuance rate does not automatically mean a project is fraudulent, but it does require context."], related: ["tokenomics", "circulating-supply", "max-supply", "burn", "staking"], sources: [sources.ethereumTokens, sources.ethereumStaking] },
  { slug: "burn", term: "Burn", category: "Tokenomics", shortDefinition: "A token burn removes units from practical circulation by sending them to an inaccessible address or using a protocol rule.", answer: "A token burn is an action intended to make tokens unspendable or permanently reduce a supply measure. The effect depends on the asset’s total supply, future issuance, demand, and whether the burn is independently verifiable.", whyItMatters: "Burn language can sound like scarcity marketing. A burn should be checked on-chain and evaluated against the amount issued, the purpose of the tokens, and any remaining mint authority.", example: "A contract sends 1 million units to a known irrecoverable address. The public transaction shows the movement, but the economic effect depends on the token’s broader supply and demand.", misconceptions: ["Burning tokens does not guarantee a price increase.", "A transfer to a burn address is not the same as destroying every related contract permission."], related: ["tokenomics", "max-supply", "inflation-rate", "circulating-supply"], sources: [sources.ethereumTokens] },
  { slug: "vesting", term: "Vesting", category: "Tokenomics", shortDefinition: "Vesting is a schedule that controls when allocated tokens become transferable or claimable.", answer: "A vesting schedule releases tokens over time, often after a cliff or through periodic unlocks. It is commonly used for teams, investors, grants, and treasury allocations.", whyItMatters: "Future unlocks can affect circulating supply, sell-side pressure, governance control, and investor expectations. The schedule should be compared with actual contract balances and wallet behavior where possible.", example: "A contributor allocation has a one-year cliff followed by monthly releases over two years. The tokens may exist in a contract today but not be transferable by the contributor until each release.", misconceptions: ["Vested does not always mean immediately liquid; a cliff or claim process may still apply.", "A vesting schedule cannot by itself prove that insiders will not sell."], related: ["circulating-supply", "tokenomics", "max-supply", "inflation-rate"], sources: [sources.ethereumTokens, sources.secInvestor] },
];

export const glossaryTerms = glossary;
export const glossaryBySlug = new Map(glossary.map((term) => [term.slug, term]));
